using OpenCvSharp;
namespace Link360Desktop;
internal sealed class VapeAlertForm:Form {
 readonly LocalObsRpc frames=new();readonly VapeObsAlert alert=new();readonly VapeDetector detector=new();readonly VapeAlertGate cooldown=new();readonly VapeEventPolicy sequence=new();readonly CancellationTokenSource life=new();
 readonly PictureBox preview=new(){Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.Black};readonly Label status=SuiteTheme.Label("Manual alert is ready. Automatic timing failed live validation; experimental mode stays off by default.");
 readonly CheckBox armed=new(){Text="Vape + plume alerts · experimental",AutoSize=true},voice=new(){Text="OBS voice",Checked=true,AutoSize=true};readonly NumericUpDown seconds=new(){Minimum=10,Maximum=120,Value=20,Width=70};
 CancellationTokenSource effect=new();readonly System.Windows.Forms.Timer timer=new(){Interval=200};bool reading,firing;byte[]? latest;Rect selection;System.Drawing.Point? drag;int alertCount;DateTime lastFrame=DateTime.MinValue;string? frameHash;
 public VapeAlertForm(){Text="LINK360 Community · VAPE ALERT lab";Width=950;Height=740;MinimumSize=new System.Drawing.Size(850,650);BackColor=SuiteTheme.Background;ForeColor=SuiteTheme.Text;Font=new Font("Segoe UI",10);
 var layout=new TableLayoutPanel(){Dock=DockStyle.Fill,Padding=new Padding(20),RowCount=5,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,58));Controls.Add(layout);
 layout.Controls.Add(SuiteTheme.Label("VAPE ALERT! · local effect lab",22,true),0,0);layout.Controls.Add(preview,0,1);status.Dock=DockStyle.Fill;status.AutoSize=false;layout.Controls.Add(status,0,2);
 var row=new FlowLayoutPanel(){Dock=DockStyle.Fill};row.Controls.Add(SuiteTheme.Button("Start preview",()=>timer.Start()));row.Controls.Add(SuiteTheme.Button("Learn selected vape",Learn));row.Controls.Add(SuiteTheme.Button("Trigger VAPE ALERT",()=>_ = Fire()));row.Controls.Add(SuiteTheme.Button("Stop",Stop));layout.Controls.Add(row,0,3);
 var options=new FlowLayoutPanel(){Dock=DockStyle.Fill};options.Controls.Add(armed);options.Controls.Add(voice);options.Controls.Add(SuiteTheme.Label("Cooldown sec"));options.Controls.Add(seconds);layout.Controls.Add(options,0,4);SuiteTheme.Inputs(this);
 timer.Tick+=async(_,_)=>await Read();preview.MouseDown+=(_,e)=>drag=e.Location;preview.MouseUp+=(_,e)=>{if(drag is not {} start)return;drag=null;var a=ImagePoint(start);var b=ImagePoint(e.Location);selection=new Rect(Math.Min(a.X,b.X),Math.Min(a.Y,b.Y),Math.Abs(a.X-b.X),Math.Abs(a.Y-b.Y));status.Text="Selection ready · click Learn selected vape";};
 bool closing=false,canClose=false;FormClosing+=async(_,e)=>{if(canClose)return;e.Cancel=true;if(closing)return;closing=true;Stop();life.Cancel();while(reading||firing)await Task.Delay(25);try{using var cleanup=new CancellationTokenSource(12000);await alert.Hide(cleanup.Token);}catch(Exception error){System.Diagnostics.Debug.WriteLine("Local alert cleanup: "+error.Message);}finally{timer.Dispose();preview.Image?.Dispose();detector.Dispose();await frames.DisposeAsync();await alert.DisposeAsync();effect.Dispose();life.Dispose();canClose=true;Close();}};
 }
 OpenCvSharp.Point ImagePoint(System.Drawing.Point p){double scale=Math.Min(preview.Width/640.0,preview.Height/360.0);return new((int)Math.Clamp((p.X-(preview.Width-640*scale)/2)/scale,0,639),(int)Math.Clamp((p.Y-(preview.Height-360*scale)/2)/scale,0,359));}
 void Stop(){effect.Cancel();effect.Dispose();effect=new();armed.Checked=false;timer.Stop();detector.Reset();sequence.Reset();status.Text="Stopped · automatic alerts off";}
 void Learn(){try{if(latest==null)throw new IOException("Start preview first.");using var mat=Cv2.ImDecode(latest,ImreadModes.Color);detector.Learn(mat,selection);sequence.Reset();status.Text="Vape reference learned in memory only · not an identity classifier";}catch(Exception e){status.Text=e.Message;}}
 async Task Read(){if(reading||life.IsCancellationRequested)return;reading=true;try{
 var data=await frames.Call("GetSourceScreenshot",new{sourceName="Main Camera - SELECT INSTA360 LINK",imageFormat="jpg",imageWidth=640,imageHeight=360,imageCompressionQuality=85},life.Token);life.Token.ThrowIfCancellationRequested();string url=data.GetProperty("imageData").GetString()!;latest=Convert.FromBase64String(url[(url.IndexOf(',')+1)..]);var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(latest));if(hash==frameHash){if(DateTime.UtcNow-lastFrame>TimeSpan.FromSeconds(2)){detector.Reset();sequence.Reset();status.Text="Camera image unchanged · automatic alerts held";}return;}frameHash=hash;lastFrame=DateTime.UtcNow;
 using var mat=Cv2.ImDecode(latest,ImreadModes.Color);using var faceImage=new Mat();Cv2.Resize(mat,faceImage,new OpenCvSharp.Size(320,180));var faces=LocalFaceDetector.Detect(faceImage.ToBytes(".jpg"));Rect? face=faces.Faces.Length==1?new Rect((int)(faces.Faces[0].X*320/faces.Width),(int)(faces.Faces[0].Y*180/faces.Height),Math.Max(1,(int)(faces.Faces[0].Width*320/faces.Width)),Math.Max(1,(int)(faces.Faces[0].Height*180/faces.Height))):null;var signal=detector.Observe(mat,DateTime.UtcNow,face:face);bool nearMouth=face is {} f&&signal.TemplateScore>=.86&&signal.VapeBox is {} vb&&Math.Abs(vb.X+vb.Width/2.0-(f.X+f.Width/2.0)*2)<f.Width*3&&vb.Y>=(f.Y+f.Height*.35)*2&&vb.Y<=(f.Bottom+f.Height*.6)*2;bool eventReady=sequence.Observe(DateTime.UtcNow,armed.Checked,face!=null,nearMouth,signal.Candidate,signal.PlumeFraction,signal.ChangedFraction);if(signal.VapeBox is {} box)Cv2.Rectangle(mat,box,new Scalar(80,240,100),2);if(selection.Width>0&&selection.Height>0)Cv2.Rectangle(mat,selection,new Scalar(255,180,30),1);
 using var ms=new MemoryStream(mat.ToBytes(".bmp"));using var img=Image.FromStream(ms);var old=preview.Image;preview.Image=new Bitmap(img);old?.Dispose();status.Text=$"{sequence.Status}\nPlume cue {signal.PlumeFraction:P1} · scene change {signal.ChangedFraction:P1} · vape reference {signal.TemplateScore:P0} · face {face!=null} · near mouth {nearMouth} · alerts {alertCount} · no frames saved";
 if(eventReady&&!firing&&cooldown.Try(DateTime.UtcNow,TimeSpan.FromSeconds((double)seconds.Value)))_ = Fire();
 }catch(OperationCanceledException){}catch(Exception e){armed.Checked=false;detector.Reset();sequence.Reset();status.Text="Alert preview held · "+e.Message;}finally{reading=false;}}
 async Task Fire(){if(firing)return;firing=true;try{status.Text="VAPE ALERT! · showing in current OBS scene";using var both=CancellationTokenSource.CreateLinkedTokenSource(effect.Token,life.Token);await alert.Fire(voice.Checked,both.Token);alertCount++;if(!IsDisposed)status.Text=$"Alert finished · {alertCount} completed · OBS overlay hidden";}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)status.Text="OBS alert failed · "+e.Message;}finally{firing=false;}}
}
